/** מוט ה-A — בכחול בלוגו המקורי. קו ישר, ולכן מלבן ולא נתיב מותווה. */
const WORDMARK_ACCENT_PATH = "M4.1 13.79L15.05 13.79L15.05 14.05L4.1 14.05Z";

/**
 * המילולוגו לבדו. `height` הוא גובה הקופסה כולה (כולל היורד של ה-p), לא גובה
 * האות הרישית — הרוחב נגזר ממנו ביחס קבוע.
 */
export function Wordmark({
  height = 24,
  className,
  title = he.site.brand,
}: {
  height?: number;
  className?: string;
  title?: string;
}) {
  return (
    <svg
      height={height}
      width={(height * 102.7) / 27.6}
      viewBox="0 0 102.7 27.6"
      className={className}
      role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true}
      aria-label={title || undefined}
      focusable="false"
    >
      {title && <title>{title}</title>}
      <path d={WORDMARK_PATH} fill="var(--color-graphite, #202326)" />
      <path d={WORDMARK_ACCENT_PATH} fill="var(--color-lapis, #3f6297)" />
    </svg>
  );
}

/**
 * שורת ה-DESIGNS שמתחת למילולוגו, עם שני הקווים הכחולים משני הצדדים.
 *
 * טקסט חי ולא ווקטור: זו סתם רשומית מרווחת, והיא נראית נכון בכל גופן סנס —
 * בניגוד למילולוגו, שהאותיות שלו הן הצורה עצמה. `dir="ltr"` כי המילה לטינית
 * ויושבת בתוך עמוד RTL.
 */
export function BrandSub({ className }: { className?: string }) {
  return (
    <span
      dir="ltr"
      className={`flex items-center gap-[0.9em] text-[0.62em] leading-none ${className ?? ""}`}
      aria-hidden="true"
    >
      <span className="h-[1.6em] w-px bg-lapis" />
      <span className="font-display font-light tracking-[0.62em] text-graphite">
        {he.site.brandSub}
      </span>
      <span className="h-[1.6em] w-px bg-lapis" />
    </span>
  );
}

/**
 * הנעילה המלאה: הסימן ואחריו המילולוגו, בשורה אחת.
 *
 * `stacked` מציב את הסימן מעל המילולוגו כמו בלוגו המקורי — לשטח שיש בו גובה
 * (פוטר, תמונת שיתוף) ולא לרוחב של הדר. `withSub` מוסיף את שורת ה-DESIGNS;
 * היא אינה חייבת להופיע, ובהדר היא רק מרעישה.
 */
export default function BrandLockup({
  height = 24,
  stacked = false,
  withSub = false,
  align = "center",
  className,
  title = he.site.brand,
}: {
  height?: number;
  stacked?: boolean;
  withSub?: boolean;
  /** לאיזה צד נדחפת הנעילה בתוך ההורה שלה, בסידור המוער. **פיזי ולא לוגי**:
   *  הנעילה עצמה `dir="ltr"` — לוגו הוא יצירה קבועה ואינו מתהפך עם כיוון
   *  הטקסט — ולכן יישור לוגי היה נצמד לשמאל דווקא בעמוד RTL. הפריטים בתוכה
   *  נשארים ממורכזים זה מול זה בכל מקרה, כמו בלוגו המקורי. */
  align?: "left" | "center" | "right";
  className?: string;
  title?: string;
}) {
  // הסימן קצת גדול מגובה המילולוגו בשורה אחת, כדי ששניהם ייראו באותו משקל
  // אופטי: המילולוגו הוא בעיקר חלל לבן, והסימן הוא קו סגור.
  const markSize = stacked ? height * 1.9 : height * 1.55;
  return (
    <span
      dir="ltr"
      className={`flex w-fit ${
        stacked
          ? `flex-col items-center gap-[0.5em] ${
              align === "left" ? "mr-auto" : align === "right" ? "ml-auto" : "mx-auto"
            }`
          : "flex-row items-center gap-[0.55em]"
      } ${className ?? ""}`}
      style={{ fontSize: height }}
    >
      {/* הסימן `aria-hidden`: השם נקרא פעם אחת, מהמילולוגו שלצידו. */}
      <BrandMark size={markSize} />
      <Wordmark height={height} title={title} />
      {withSub && <BrandSub className="mt-[0.15em]" />}
    </span>
  );
}
